<script setup>
import {reactive,ref,watch} from 'vue';import {useRouter} from 'vue-router';import {api,messageOf} from '../api';import {applyRecommendedPrice,buildPublishPayload} from '../pricing'
const router=useRouter(),busy=ref(false),error=ref(''),pricingBusy=ref(false),pricingError=ref(''),pricingResult=ref(null),pricingStale=ref(false);const form=reactive({title:'',description:'',category:'日用',tradeType:'FREE',price:null,brandModel:'',purchasePrice:null,usageDuration:'',condition:'',defects:'',accessories:'',pickupLocation:'',slots:[{startAt:'',endAt:''}]});const addSlot=()=>{if(form.slots.length<5)form.slots.push({startAt:'',endAt:''})};const removeSlot=i=>form.slots.splice(i,1);const local=v=>v?`${v}:00`:null;
const pricingInput=()=>({tradeType:form.tradeType,title:form.title,category:form.category,description:form.description,brandModel:form.brandModel||null,purchasePrice:form.purchasePrice===''?null:form.purchasePrice,usageDuration:form.usageDuration||null,condition:form.condition||null,defects:form.defects||null,accessories:form.accessories||null});
watch(()=>[form.title,form.description,form.category,form.tradeType,form.brandModel,form.purchasePrice,form.usageDuration,form.condition,form.defects,form.accessories],()=>{if(pricingResult.value)pricingStale.value=true;if(form.tradeType!=='FIXED_PRICE'){pricingResult.value=null;pricingError.value='';pricingStale.value=false}});
async function estimate(){pricingBusy.value=true;pricingError.value='';pricingResult.value=null;pricingStale.value=false;try{pricingResult.value=(await api.post('/ai/pricing',pricingInput())).data}catch(e){pricingError.value=messageOf(e)}finally{pricingBusy.value=false}}
function useRecommended(){if(applyRecommendedPrice(form,pricingResult.value))pricingStale.value=false}
async function submit(){error.value='';if(!form.title.trim()||!form.description.trim()||!form.pickupLocation.trim()){error.value='请完整填写物品与公共交接地点';return}if(form.tradeType==='FIXED_PRICE'&&(!form.price||Number(form.price)<=0)){error.value='标价必须大于0元';return}if(form.slots.some(x=>!x.startAt||!x.endAt||x.endAt<=x.startAt)){error.value='请填写有效的未来时段';return}busy.value=true;try{const payload=buildPublishPayload(form);const {data}=await api.post('/items',payload);router.push(`/items/${data.id}`)}catch(e){error.value=messageOf(e);if(e.response?.status===401)router.push('/login')}finally{busy.value=false}}
</script>
<template><section class="panel publish-panel"><p class="eyebrow">发布闲置</p><h1>把物品交给刚好需要的邻居</h1><form @submit.prevent="submit"><label>物品名称<input v-model="form.title" maxlength="100"></label><label>描述<textarea v-model="form.description" maxlength="2000" rows="5"></textarea></label><div class="form-row"><label>分类<select v-model="form.category"><option>日用</option><option>家电</option><option>图书</option><option>数码</option><option>其他</option></select></label><label>交易方式<select v-model="form.tradeType"><option value="FREE">免费送</option><option value="NEGOTIABLE">随便给</option><option value="FIXED_PRICE">标价</option></select></label></div><template v-if="form.tradeType==='FIXED_PRICE'"><label>最终价格（元）<input v-model.number="form.price" type="number" min="0.01" step="0.01"></label><section class="ai-pricing"><div><p class="eyebrow">AI 定价参考</p><h2>补充信息，让估价更可靠</h2></div><div class="form-row"><label>品牌／型号（可选）<input v-model="form.brandModel" maxlength="120"></label><label>购入价格（可选）<input v-model.number="form.purchasePrice" type="number" min="0" step="0.01"></label></div><div class="form-row"><label>使用时间（可选）<input v-model="form.usageDuration" maxlength="100" placeholder="例如：约一年"></label><label>成色情况<input v-model="form.condition" maxlength="300"></label></div><label>已知缺陷<textarea v-model="form.defects" maxlength="500" rows="2"></textarea></label><label>配件情况<textarea v-model="form.accessories" maxlength="300" rows="2"></textarea></label><button type="button" :disabled="pricingBusy" @click="estimate">{{pricingBusy?'AI估价中…':'AI帮我估价'}}</button><p class="ai-disclaimer">该结果未查询实时二手成交行情，仅供参考，最终价格由你决定。</p><p v-if="pricingError" class="error">{{pricingError}} 手动填写价格仍可正常发布。</p><p v-if="pricingStale" class="stale">估价信息已修改，请重新估价后再参考旧结果。</p><div v-if="pricingResult?.status==='NEED_MORE_INFO'" class="pricing-result"><h3>还需要补充信息</h3><p v-if="pricingResult.missingFields?.length">缺少：{{pricingResult.missingFields.join('、')}}</p><ul><li v-for="q in pricingResult.questions" :key="q">{{q}}</li></ul></div><div v-else-if="pricingResult?.status==='ESTIMATE'" class="pricing-result"><p class="price-range">建议区间：¥{{pricingResult.minPrice}}～¥{{pricingResult.maxPrice}}</p><p><strong>推荐挂牌价：¥{{pricingResult.recommendedPrice}}</strong> · 置信度 {{pricingResult.confidence}}</p><p>{{pricingResult.rationale}}</p><ul><li v-for="f in pricingResult.factors" :key="f">{{f}}</li></ul><p class="hint">不确定性：{{pricingResult.uncertainty}}</p><button type="button" class="secondary" :disabled="pricingStale" @click="useRecommended">填入推荐价</button></div></section></template><label>公共交接地点<input v-model="form.pickupLocation" maxlength="200"></label><fieldset><legend>可选交接时段（北京时间）</legend><div v-for="(slot,i) in form.slots" :key="i" class="slot-edit"><input v-model="slot.startAt" type="datetime-local"><span>至</span><input v-model="slot.endAt" type="datetime-local"><button v-if="form.slots.length>1" type="button" class="secondary" @click="removeSlot(i)">删除</button></div><button v-if="form.slots.length<5" type="button" class="secondary" @click="addSlot">添加时段</button></fieldset><p v-if="error" class="error">{{error}}</p><button :disabled="busy">{{busy?'发布中…':'确认发布'}}</button></form></section></template>